package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen5Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter out;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        out = new StringWriter();
    }









    @Test
    public void testTranslate_DecimalHighValue() throws IOException {
        // &#128512; is 😀 (U+1F600)
        int result = unescaper.translate("&#128512;", 0, out);
        // length calculation: 2 (&#) + (5 digits) + 1 (;) = 8
        // Wait, let's trace the code: 2 + (end - start) + (isHex ? 1 : 0) + 1
        // start = 2, end = 7. end-start = 5. isHex = false. 2 + 5 + 0 + 1 = 8.
        assertEquals(8, result);
        assertEquals("😀", out.toString());
    }














}

